import datetime
import re

from ta_moler.events.unix_syslog.genericunix_syslog_lineevent import GenericUnixSyslogLineEvent


class ShutdownRequested(GenericUnixSyslogLineEvent):
    """BTS crash event class."""

    # Example line: reboot:  Shutdown requested by 32285 (bash)
    _re_bts_crash_detected = re.compile(r"reboot:\s+Shutdown requested by \d+")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for bts crash.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(ShutdownRequested, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[ShutdownRequested._re_bts_crash_detected],
            match="any",
        )


